WITH PoliticalScienceSubjectStats AS ( SELECT s.SUBJECT_CODE, s.SUBJECT_CODE_DESC, EXP(AVG(LN(student_count))) AS geometric_mean_students, SUM(student_count) AS total_students FROM SIS_SUBJECT_CODE s JOIN SIS_DEPARTMENT d ON s.DEPARTMENT_CODE = d.DEPARTMENT_CODE JOIN ( SELECT DEPARTMENT, COUNT(*) AS student_count FROM MIT_STUDENT_DIRECTORY GROUP BY DEPARTMENT ) m ON d.DEPARTMENT_CODE = m.DEPARTMENT WHERE d.IS_DEGREE_GRANTING = 'Y' AND d.DEPARTMENT_NAME = 'Political Science' GROUP BY s.SUBJECT_CODE, s.SUBJECT_CODE_DESC ), DepartmentUnitsStats AS ( SELECT icte.DEPARTMENT_NAME, sd.SCHOOL_NAME, icte.avg_total_units, icte.total_units_range, icte.total_units_variance, ad.DEPARTMENT_PHONE_NUMBER, sd.DEPARTMENT_CODE FROM ( SELECT SIS_COURSE_DESCRIPTION.DEPARTMENT_NAME, AVG(COURSE_CATALOG_SUBJECT_OFFERED.TOTAL_UNITS) AS avg_total_units, MAX(COURSE_CATALOG_SUBJECT_OFFERED.TOTAL_UNITS) - MIN(COURSE_CATALOG_SUBJECT_OFFERED.TOTAL_UNITS) AS total_units_range, VARIANCE(COURSE_CATALOG_SUBJECT_OFFERED.TOTAL_UNITS) AS total_units_variance FROM SIS_SUBJECT_CODE JOIN SIS_COURSE_DESCRIPTION ON SIS_SUBJECT_CODE.COURSE_NUMBER = SIS_COURSE_DESCRIPTION.COURSE JOIN COURSE_CATALOG_SUBJECT_OFFERED ON SIS_COURSE_DESCRIPTION.COURSE = COURSE_CATALOG_SUBJECT_OFFERED.SUBJECT_CODE WHERE COURSE_CATALOG_SUBJECT_OFFERED.ACADEMIC_YEAR = 2022 AND SIS_COURSE_DESCRIPTION.IS_DEGREE_GRANTING = 'Y' AND SIS_COURSE_DESCRIPTION.DEPARTMENT_NAME <> 'Mathematics' AND SIS_COURSE_DESCRIPTION.DEPARTMENT <> '18' GROUP BY SIS_COURSE_DESCRIPTION.DEPARTMENT_NAME ) icte LEFT JOIN SIS_DEPARTMENT sd ON icte.DEPARTMENT_NAME = sd.DEPARTMENT_NAME LEFT JOIN SIS_ADMIN_DEPARTMENT ad ON sd.DEPARTMENT_CODE = ad.SIS_ADMIN_DEPARTMENT_CODE ) SELECT ps.SUBJECT_CODE, ps.SUBJECT_CODE_DESC, ps.geometric_mean_students, ps.total_students, du.DEPARTMENT_NAME, du.SCHOOL_NAME, du.avg_total_units, du.total_units_range, du.total_units_variance, du.DEPARTMENT_PHONE_NUMBER FROM PoliticalScienceSubjectStats ps JOIN SIS_SUBJECT_CODE ssc ON ps.SUBJECT_CODE = ssc.SUBJECT_CODE JOIN SIS_DEPARTMENT sd ON ssc.DEPARTMENT_CODE = sd.DEPARTMENT_CODE JOIN DepartmentUnitsStats du ON sd.DEPARTMENT_CODE = du.DEPARTMENT_CODE GROUP BY ps.SUBJECT_CODE, ps.SUBJECT_CODE_DESC, ps.geometric_mean_students, ps.total_students, du.DEPARTMENT_NAME, du.SCHOOL_NAME, du.avg_total_units, du.total_units_range, du.total_units_variance, du.DEPARTMENT_PHONE_NUMBER ORDER BY ps.SUBJECT_CODE, du.SCHOOL_NAME, du.DEPARTMENT_NAME;